#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int soundex_digit(char c) {
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0) {
        puts("EMPTY");
        return 0;
    }
    char code[4];
    // First letter (uppercase)
    code[0] = toupper((unsigned char)input[0]);
    int last_digit = soundex_digit(code[0]);
    int pos = 1; // next position in code
    for (size_t i = 1; i < len && pos < 4; ++i) {
        char ch = toupper((unsigned char)input[i]);
        int d = soundex_digit(ch);
        if (d == 0) {
            // Vowels and H, W, Y are ignored but reset last_digit only for H/W? Standard algorithm resets only when d != 0, so we just continue.
            continue;
        }
        if (d == last_digit) {
            continue; // skip duplicate codes
        }
        code[pos++] = '0' + d;
        last_digit = d;
    }
    // Pad with zeros if needed
    while (pos < 4) {
        code[pos++] = '0';
    }
    // Ensure null-termination for puts
    char out[5];
    memcpy(out, code, 4);
    out[4] = '\0';
    puts(out);
    return 0;
}
